export function translate(value: string, language: AppLanguage = getLanguage()) {
  return language === "ro" ? ro[value] || value : value;
}

export function formatMessage(template: string, values: Record<string, string | number>, language: AppLanguage = getLanguage()) {
  return translate(template, language).replace(/\{(\w+)\}/g, (match, key: string) =>
    Object.prototype.hasOwnProperty.call(values, key) ? String(values[key]) : match);
}

export function translateAccessibility(value: string, language: AppLanguage = getLanguage()) {
  if (language !== "ro") return value;
  const exact = translate(value, language);
  if (exact !== value) return exact;
  const templates: [RegExp, string][] = [
    [/^Explore places in (.+)$/, "Explore places in {city}"],
    [/^Photo source and license for (.+)$/, "Photo source and license for {name}"],
    [/^Add (.+) to favorites$/, "Add {name} to favorites"],
    [/^Open (.+) on map$/, "Open {name} on map"],
    [/^Open (.+) trip record$/, "Open {name} trip record"],
    [/^Delete (.+) trip$/, "Delete {name} trip"],
    [/^Find places near (.+)$/, "Find places near {name}"],
    [/^Map for (.+)$/, "Map for {name}"],
    [/^Photo of (.+)$/, "Photo of {name}"],
    [/^(Explore|View|Save|Unsave|Preview|Edit) (.+)$/, ""],
  ];
  for (const [pattern, template] of templates) {
    const match = value.match(pattern);
    if (!match) continue;
    const name = match[match.length - 1];
    return formatMessage(template || `${match[1]} {name}`, { name, city: name }, language);
  }
  return value;
}
